def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a <= 1:
        return False

    # Function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime factors of a
    prime_factors = []
    temp = a
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            prime_factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        prime_factors.append(temp)

    # Check if we have exactly 3 prime factors (counting multiplicities)
    if len(prime_factors) != 3:
        return False

    # Verify all factors are prime (should be true by construction, but double-check)
    for factor in prime_factors:
        if not is_prime(factor):
            return False

    return True
